import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Block Types","description":"All blocks available in ApptiveGrid pages, with their settings.","frontmatter":{"title":"Block Types","description":"All blocks available in ApptiveGrid pages, with their settings."},"headers":[],"relativePath":"en/referenz/blocktypen.md","filePath":"en/referenz/blocktypen.md","lastUpdated":1787319236000}'),n={name:"en/referenz/blocktypen.md"};function s(d,t,i,l,c,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="block-types-—-reference" tabindex="-1">Block Types — Reference <a class="header-anchor" href="#block-types-—-reference" aria-label="Permalink to &quot;Block Types — Reference&quot;">​</a></h1><p>The block picker is organized into three groups. This reference follows the same order.</p><hr><h2 id="basic-blocks" tabindex="-1">Basic blocks <a class="header-anchor" href="#basic-blocks" aria-label="Permalink to &quot;Basic blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Paragraph</strong></td><td><em>Write normal text</em></td></tr><tr><td><strong>Heading 1</strong></td><td><em>Large heading</em></td></tr><tr><td><strong>Heading 2</strong></td><td><em>Medium heading</em></td></tr><tr><td><strong>Heading 3</strong></td><td><em>Small heading</em></td></tr><tr><td><strong>Page</strong></td><td><em>Add a subpage</em></td></tr><tr><td><strong>Horizontal Layout</strong></td><td><em>Arrange blocks side by side</em></td></tr><tr><td><strong>Vertical Layout</strong></td><td><em>Arrange blocks one below another</em></td></tr><tr><td><strong>Tab Layout</strong></td><td><em>Show subpages as tabs</em></td></tr><tr><td><strong>Stepper Layout</strong></td><td><em>Show subpages as steps</em></td></tr><tr><td><strong>Image</strong></td><td><em>Add an image with custom dimensions</em></td></tr></tbody></table><h3 id="paragraph-and-headings" tabindex="-1">Paragraph and headings <a class="header-anchor" href="#paragraph-and-headings" aria-label="Permalink to &quot;Paragraph and headings&quot;">​</a></h3><p>Text blocks offer <strong>Text size</strong> (heading level) and <strong>Text alignment</strong> — <em>Left</em>, <em>Center</em>, <em>Right</em>, <em>Justify</em> — plus <strong>Text color</strong>.</p><p>Empty blocks show <em>Empty paragraph…</em> or <em>Empty heading…</em> respectively.</p><h3 id="layout-blocks" tabindex="-1">Layout blocks <a class="header-anchor" href="#layout-blocks" aria-label="Permalink to &quot;Layout blocks&quot;">​</a></h3><p><strong>Horizontal</strong> and <strong>Vertical Layout</strong> arrange their contained blocks. Settings under <strong>Arrangement</strong>:</p><ul><li>Direction: <em>Side by side</em> / <em>Stacked</em></li><li>Alignment: <em>Start</em>, <em>Center</em>, <em>End</em>, <em>Top</em>, <em>Bottom</em></li><li><em>Gap between</em>, <em>Stretch</em>, <em>Wrap content</em></li></ul><p>Plus <strong>Background color</strong>, <strong>Border radius</strong>, <strong>Width</strong>, and <strong>Height</strong>.</p><p><strong>Tab Layout</strong> and <strong>Stepper Layout</strong> display subpages. Without subpages, the note <em>Add pages to see them as tabs</em> appears.</p><p>→ <a href="/en/seiten/layout-bloecke">Layout blocks</a></p><hr><h2 id="special-blocks" tabindex="-1">Special blocks <a class="header-anchor" href="#special-blocks" aria-label="Permalink to &quot;Special blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Embed</strong></td><td><em>Show any external content, such as web pages or videos</em></td></tr><tr><td><strong>Grid View</strong></td><td><em>Embed a view, e.g. Kanban, Grid, Calendar, Map, or Gallery</em></td></tr><tr><td><strong>Flow</strong></td><td><em>Embed a Flow and open it in the Flow editor</em></td></tr><tr><td><strong>File List</strong></td><td><em>List view with drag-and-drop file upload</em></td></tr><tr><td><strong>Button</strong></td><td><em>Button to start a form or a Flow</em></td></tr><tr><td><strong>QR Code</strong></td><td><em>QR code for a form or a Flow</em></td></tr><tr><td><strong>Counter</strong></td><td><em>Count the number of entries in a view</em></td></tr><tr><td><strong>Sum Card</strong></td><td><em>Sums the values of a numeric column in a view</em></td></tr><tr><td><strong>Donut Chart</strong></td><td><em>Shows the distribution of values in a Single Select column</em></td></tr><tr><td><strong>Date Forecast</strong></td><td><em>Compares planned dates with current and earlier estimates</em></td></tr><tr><td><strong>HTML</strong></td><td><em>Embed your own HTML or generate it with AI</em></td></tr><tr><td><strong>Grid List</strong></td><td><em>Create a list based on entries from a Grid</em></td></tr></tbody></table><h3 id="grid-view" tabindex="-1">Grid View <a class="header-anchor" href="#grid-view" aria-label="Permalink to &quot;Grid View&quot;">​</a></h3><p>Embeds an existing view into the page — the most important block for portals.</p><p><strong>Settings:</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Grid View</strong></td><td>Which view is embedded</td></tr><tr><td><strong>Show full width</strong></td><td>View spans the full page width</td></tr><tr><td><strong>Show search</strong></td><td>Search field for visitors</td></tr><tr><td><strong>Show filter</strong></td><td>Filter for visitors</td></tr><tr><td><strong>Show CSV download</strong></td><td>Export for visitors</td></tr><tr><td><strong>Read-only entries</strong></td><td>Prevents editing</td></tr><tr><td><strong>Don&#39;t open detail view</strong></td><td>Clicking a row opens nothing</td></tr><tr><td><strong>Hide title</strong></td><td>Hides the view title</td></tr><tr><td><strong>Button color</strong></td><td>Color of the controls</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Two switches for read-only portals</p><p>For a purely display-only portal, <em>Read-only entries</em> alone isn&#39;t always enough. Also turn on <em>Don&#39;t open detail view</em>, or visitors can still reach the single-entry view.</p><p>If the switch is off, only people with edit rights on the Grid can edit — not automatically every visitor. → <a href="/en/seiten/portal-veroeffentlichen">Publishing a portal</a></p></div><div class="tip custom-block"><p class="custom-block-title">The view&#39;s filter still applies</p><p>The embedded view carries its filter and hidden columns along. For a portal, create a dedicated view that shows only the data you intend to share, instead of embedding an internal working view.</p></div><h3 id="analytics-blocks" tabindex="-1">Analytics blocks <a class="header-anchor" href="#analytics-blocks" aria-label="Permalink to &quot;Analytics blocks&quot;">​</a></h3><p><strong>Counter</strong> shows the number of entries in a view.</p><p><strong>Sum Card</strong> sums a numeric column. Messages:</p><ul><li><em>This view has no summable numeric columns</em> — a column of type Number, Decimal, or Currency is missing</li><li><em>This view has more than {maxRows} rows. The sum only covers the first {maxRows} rows.</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Sums are incomplete in large views</p><p>Beyond a certain row count, the block only sums the beginning of the view. For reliable totals, a <a href="/en/ansichten/filtern-sortieren-gruppieren">grouping with an aggregate</a> or a field of type <em>Calculate sum</em> is the safe approach.</p></div><p><strong>Donut Chart</strong> shows the distribution across a column of type <strong>Single Select</strong>. Without such a column, the block doesn&#39;t work.</p><h3 id="button-and-qr-code" tabindex="-1">Button and QR Code <a class="header-anchor" href="#button-and-qr-code" aria-label="Permalink to &quot;Button and QR Code&quot;">​</a></h3><p>Both link to a form or a Flow and start it. The QR code block is well suited for posters and printed material.</p><h3 id="file-list" tabindex="-1">File List <a class="header-anchor" href="#file-list" aria-label="Permalink to &quot;File List&quot;">​</a></h3><p>List view with drag-and-drop upload. Hint in the drop area: <em>Drop files here to create new entries</em>. Feedback: <em>{count} file(s) were uploaded and saved</em> or <em>… could not be uploaded</em>.</p><h3 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h3><p>Your own HTML code with a <strong>live preview</strong>.</p><ul><li><strong>Generate with AI</strong> — describe changes instead of writing them</li><li><strong>Restore previous HTML version</strong></li><li><strong>Auto-adjust height</strong></li><li>Template variables with <code>{{ }}</code>, for example <code>{{variableName}}</code></li></ul><p>Errors show <em>Preview error</em>; a failed generation shows <em>HTML could not be generated</em>.</p><h3 id="grid-list" tabindex="-1">Grid List <a class="header-anchor" href="#grid-list" aria-label="Permalink to &quot;Grid List&quot;">​</a></h3><p>Builds a list from the entries of a Grid. You choose the Grid (<em>Select Grid</em>) and design a template block that repeats for each entry (<em>Edit list item</em>).</p><h3 id="embed" tabindex="-1">Embed <a class="header-anchor" href="#embed" aria-label="Permalink to &quot;Embed&quot;">​</a></h3><p>Embeds external content via an iframe — web pages, videos, documents.</p><h3 id="date-forecast" tabindex="-1">Date Forecast <a class="header-anchor" href="#date-forecast" aria-label="Permalink to &quot;Date Forecast&quot;">​</a></h3><p>Compares planned dates with current and earlier estimates. The use case is not further explained in the interface.</p><hr><h2 id="form-field-blocks" tabindex="-1">Form field blocks <a class="header-anchor" href="#form-field-blocks" aria-label="Permalink to &quot;Form field blocks&quot;">​</a></h2><p>The same input fields used in forms, freely placeable on the page.</p><table tabindex="0"><thead><tr><th>Block</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Single-line Text Field</strong></td><td><em>For short input like name, company, or subject</em></td></tr><tr><td><strong>Multi-line Text Field</strong></td><td><em>For longer input like comments or descriptions</em></td></tr><tr><td><strong>Barcode Scanner</strong></td><td><em>Scan QR codes and 2D barcodes with the camera</em></td></tr><tr><td><strong>E-Mail</strong></td><td><em>Insert an e-mail address</em></td></tr><tr><td><strong>Phone Number</strong></td><td>–</td></tr><tr><td><strong>Date</strong></td><td>–</td></tr><tr><td><strong>Date and time</strong></td><td>–</td></tr><tr><td><strong>Decimal</strong></td><td><em>Insert a number with decimal places</em></td></tr><tr><td><strong>Number</strong></td><td><em>Insert a whole number</em></td></tr><tr><td><strong>Rating Scale</strong></td><td><em>Capture ratings with numbers, stars, or emoji</em></td></tr><tr><td><strong>Selection as dropdown</strong></td><td><em>Select a value from a dropdown menu</em></td></tr><tr><td><strong>Selection as list</strong></td><td><em>Select a value from a list</em></td></tr><tr><td><strong>Multiple Select</strong></td><td><em>Select several values from a list</em></td></tr><tr><td><strong>Checkmark</strong></td><td><em>Add a checkbox to your page</em></td></tr><tr><td><strong>Decision</strong></td><td><em>Shows a yes/no decision and stores the choice as a true/false value</em></td></tr><tr><td><strong>Signature</strong></td><td><em>Insert a signature</em></td></tr><tr><td><strong>Entry</strong></td><td><em>Select an entry from a Grid</em></td></tr><tr><td><strong>Entries</strong></td><td><em>Select several entries from a Grid</em></td></tr><tr><td><strong>Address</strong></td><td>–</td></tr><tr><td><strong>Geolocation</strong></td><td><em>Add a location to your form</em></td></tr><tr><td><strong>URL</strong></td><td><em>Insert a link to a web page</em></td></tr><tr><td><strong>Upload files or photos</strong></td><td><em>Upload photos or files, on a smartphone also via the camera</em></td></tr><tr><td><strong>Currency</strong></td><td>–</td></tr><tr><td><strong>Video</strong></td><td><em>Add a required video to your form</em></td></tr><tr><td><strong>Voice Recording</strong></td><td><em>Make a voice recording</em></td></tr><tr><td><strong>Upload video</strong></td><td><em>Record a video and upload it</em></td></tr><tr><td><strong>Photo Camera</strong></td><td><em>Take a photo and upload it</em></td></tr><tr><td><strong>HTML with form fields</strong></td><td><em>Embed your own HTML and add form fields with AI</em></td></tr></tbody></table><h3 id="rating-scale" tabindex="-1">Rating Scale <a class="header-anchor" href="#rating-scale" aria-label="Permalink to &quot;Rating Scale&quot;">​</a></h3><p>Captures ratings as a number, displayed with stars or emoji.</p><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Shows a yes/no choice as cards and stores it as a boolean. Clearer than a checkmark when the decision needs to be made deliberately.</p><h3 id="recording-blocks" tabindex="-1">Recording blocks <a class="header-anchor" href="#recording-blocks" aria-label="Permalink to &quot;Recording blocks&quot;">​</a></h3><p><strong>Voice Recording</strong>, <strong>Upload video</strong>, and <strong>Photo Camera</strong> record directly through the device. Controls: <em>START</em>, <em>PAUSE</em>, <em>CONTINUE</em>, <em>Done</em>. Without permission, <em>Please allow access to the microphone</em> appears.</p><div class="tip custom-block"><p class="custom-block-title">Combining voice recording with Flows</p><p>A voice recording can be converted to text in a Flow using the <strong>Speech to text</strong> step. That turns spoken messages into searchable entries.</p></div><h3 id="html-with-form-fields" tabindex="-1">HTML with form fields <a class="header-anchor" href="#html-with-form-fields" aria-label="Permalink to &quot;HTML with form fields&quot;">​</a></h3><p>Like the HTML block, but the contained input fields write data back.</p><div class="warning custom-block"><p class="custom-block-title">Fields need a name or id</p><p>The editor warns: <em>Input fields without a name or id are not included in the Flow payload.</em> Without one of these two attributes, the value is lost.</p></div><hr><h2 id="not-included-in-the-picker" tabindex="-1">Not included in the picker <a class="header-anchor" href="#not-included-in-the-picker" aria-label="Permalink to &quot;Not included in the picker&quot;">​</a></h2><p>Some block types exist internally but are not offered — such as <strong>Heading 4</strong>, <strong>User</strong>, <strong>Dictionary</strong>, and <strong>Multitext</strong>. They are not part of the product and are not documented here.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/bloecke">Block overview</a></li><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li><li><a href="/en/seiten/auswertungen">Embedding views and analytics</a></li></ul>',62)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
